// ══════════════════════════════════════════════════
// NORMALISER SOURCE — Drive, Gmail, Batch (v8)
// + Validation alias +scan
// + Passthrough _attachId / _attachIndex / _attachTotal
// ══════════════════════════════════════════════════
const item   = $input.first().json;
const binary = $input.first().binary || {};

// ── Helper: extraire email brut depuis formats variés ──
// "_scanner <debourouba+scan@gmail.com>" → "debourouba+scan@gmail.com"
// "debourouba+scan@gmail.com" → "debourouba+scan@gmail.com"
function extractEmail(raw) {
  if (!raw) return '';
  const angleBracket = raw.match(/<([^>]+)>/);
  if (angleBracket) return angleBracket[1].trim().toLowerCase();
  const plain = raw.match(/([^\s<>"',;]+@[^\s<>"',;]+)/);
  return plain ? plain[1].trim().toLowerCase() : raw.trim().toLowerCase();
}

// ── Validation destinataire alias +scan ──────────────
function isValidScanTarget(headers) {
  if (!headers || !Array.isArray(headers)) return true; // pas de headers = laisser passer
  const SCAN_ALIAS = ($env.GED_GMAIL_ALIAS || 'debourouba+scan@gmail.com').toLowerCase();

  const toHeader        = headers.find(h => (h.name||'').toLowerCase() === 'to');
  const deliveredHeader = headers.find(h => (h.name||'').toLowerCase() === 'delivered-to');
  const ccHeader        = headers.find(h => (h.name||'').toLowerCase() === 'cc');

  const toEmail        = extractEmail(toHeader?.value        || '');
  const deliveredEmail = extractEmail(deliveredHeader?.value || '');
  const ccEmail        = extractEmail(ccHeader?.value        || '');

  // Accepter si l'alias apparaît dans To OU Delivered-To OU CC
  return [toEmail, deliveredEmail, ccEmail].some(e => e.includes(SCAN_ALIAS));
}

// ── BATCH ──────────────────────────────────────────
if (item.source === 'BATCH') {
  return [{ json: {
    source:       'BATCH',
    fileId:       item.fileId   || '',
    gmailId:      '',
    fileName:     item.fileName || 'document.pdf',
    mimeType:     'application/pdf',
    fileUrl:      item.fileUrl  || '',
    empreinte:    '',
    hash:         '',
    _attachId:    null,
    _attachIndex: 1,
    _attachTotal: 1
  }, binary }];
}

// ── GMAIL ──────────────────────────────────────────
const isGmail = !!(item.threadId || item.historyId || Array.isArray(item.labels));

if (isGmail) {
  // Extraire headers depuis payload si disponibles (email complet)
  const headers = item.payload?.headers || null;

  // Validation alias — rejeter silencieusement si pas le bon destinataire
  if (headers && !isValidScanTarget(headers)) {
    console.warn(`Email ignoré — destinataire non reconnu. id=${item.id}`);
    // Retourner item vide qui sera filtré par le nœud suivant
    return [{ json: {
      source:        'GMAIL_IGNORE',
      fileId:        'ignore_' + item.id,
      gmailId:       item.id,
      fileName:      'ignore.pdf',
      mimeType:      'application/pdf',
      fileUrl:       '',
      empreinte:     '',
      hash:          '',
      _attachId:     null,
      _attachIndex:  1,
      _attachTotal:  0,
      _ignored:      true,
      _ignoreReason: 'Destinataire alias non reconnu'
    }}];
  }

  // Extraire from/subject depuis headers si dispo
  let fromAddress = item.from || item.From || '';
  let subject     = item.subject || item.Subject || '';
  if (headers) {
    const hFrom    = headers.find(h => h.name.toLowerCase() === 'from');
    const hSubject = headers.find(h => h.name.toLowerCase() === 'subject');
    if (hFrom)    fromAddress = hFrom.value || fromAddress;
    if (hSubject) subject     = hSubject.value || subject;
  }

  // _attachId/_attachIndex/_attachTotal injectés par 🔍 Compter & Lister PJ
  const attachId    = item._attachId    || null;
  const attachIndex = item._attachIndex || 1;
  const attachTotal = item._attachTotal || 1;
  const fileName    = item.fileName     || `facture_email_${item.id}_${attachIndex}.pdf`;

  return [{ json: {
    source:       'GMAIL',
    fileId:       `gmail_${item.id}_${attachIndex}`,
    gmailId:      item.id,
    fileName:     fileName,
    mimeType:     item.mimeType || 'application/pdf',
    fileUrl:      '',
    empreinte:    '',
    hash:         '',
    emailFrom:    fromAddress,
    emailSubject: subject,
    _attachId:    attachId,
    _attachIndex: attachIndex,
    _attachTotal: attachTotal
  }, binary }];
}

// ── GOOGLE DRIVE — fallback si données manquantes ──
if (!item.id || !item.mimeType) {
  console.warn('Source Drive incomplète — fallback. Keys:', Object.keys(item).join(','));
  return [{ json: {
    source:         'DRIVE',
    fileId:         item.id || 'unknown_' + Date.now(),
    gmailId:        '',
    fileName:       item.name || 'document_inconnu.pdf',
    mimeType:       item.mimeType || 'application/pdf',
    fileUrl:        item.webViewLink || '',
    empreinte:      '',
    hash:           '',
    _attachId:      null,
    _attachIndex:   1,
    _attachTotal:   1,
    _sourceWarning: 'Données Drive incomplètes'
  }, binary }];
}

return [{ json: {
  source:       'DRIVE',
  fileId:       item.id,
  gmailId:      '',
  fileName:     item.name || 'document.pdf',
  mimeType:     item.mimeType,
  fileUrl:      item.webViewLink || '',
  empreinte:    '',
  hash:         '',
  _attachId:    null,
  _attachIndex: 1,
  _attachTotal: 1
}, binary }];

// ══════════════════════════════════════════════════
// NETTOYAGE JSON — Parsing réponse Gemini (v7)
// Robuste : jamais de throw — fallback BASSE confiance si erreur
// ══════════════════════════════════════════════════

const inputItem = $input.first();
const item = inputItem.json;

if (inputItem.binary) {
  delete inputItem.binary;
}

const sourceItem = $('⚙️ Normaliser Source').first().json;
const now = $now.setZone('America/Toronto');

// ── Fallback complet si Gemini échoue ──────────────
function makeFallback(reason) {
  console.warn('PARSER FALLBACK:', reason);
  return [{
    json: {
      // Zone A
      date:                 now.toISODate(),
      emetteur:             'INCONNU',
      type_document:        'ADMIN',
      beneficiaire:         'ANONYME',
      objet:                'Document non analysable',
      // Zone B
      categorie:            '',
      sous_categorie:       '',
      confiance:            'BASSE',
      raison_doute:         `Analyse IA échouée : ${reason}`,
      mention_manuscrite:   null,
      // Zone C
      montant_ttc:          0,
      est_financier:        false,
      flag_mixte:           false,
      montant_pro_estime:   null,
      montant_perso_estime: null,
      ratio_pro_pct:        null,
      // Zone E
      _source:      sourceItem.source    || 'INCONNUE',
      _fileName:    sourceItem.fileName  || 'INCONNU',
      _originalUrl: sourceItem.fileUrl   || '',
      _empreinte:   sourceItem.empreinte || '',
      _hash:        sourceItem.hash      || '',
      _gmailId:     sourceItem.gmailId   || '',
      _fileId:      sourceItem.fileId    || 'INCONNU',
      _parseError:  true
    }
  }];
}

// ── Extraire texte brut de la réponse Gemini ───────
const rawText = item?.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!rawText || rawText.trim() === '') {
  return makeFallback('Réponse Gemini vide ou absente');
}

// ── Extraire bloc JSON ──────────────────────────────
const jsonMatch = rawText.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  return makeFallback('Aucun JSON trouvé dans la réponse Gemini');
}

// ── Parser JSON ─────────────────────────────────────
let parsed;
try {
  parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  return makeFallback('JSON malformé : ' + e.message);
}

// ── Date ────────────────────────────────────────────
let dateFinale = now.toISODate();
try {
  const dateInput = parsed.date || '';
  if (dateInput) {
    const dateObj = DateTime.fromISO(dateInput).setZone('America/Toronto');
    if (dateObj.isValid && dateObj.year >= 2000 && dateObj.year <= now.year + 1) {
      dateFinale = dateObj.toISODate();
    }
  }
} catch(e) {
  console.warn('Date parse error:', e.message);
}

// ── Type + Montant ───────────────────────────────────
const type = (parsed.type_document || '').toUpperCase() || 'ADMIN';
let ttc = parseFloat(parsed.montant_ttc) || 0;

// FACTURE/RECU à 0$ → confiance dégradée, pas de throw
let raison_doute = parsed.raison_doute || null;
if (['FACTURE', 'RECU'].includes(type) && ttc === 0) {
  raison_doute = (raison_doute ? raison_doute + ' — ' : '') + 'Montant TTC à 0$ pour ' + type + ' : vérification requise';
}

// ── Champs MIXTE ─────────────────────────────────────
const flagMixte = parsed.flag_mixte === true;
const montantProEstime   = flagMixte ? (parseFloat(parsed.montant_pro_estime)   || null) : null;
const montantPersoEstime = flagMixte ? (parseFloat(parsed.montant_perso_estime) || null) : null;
const ratioProPct        = flagMixte ? (parseInt(parsed.ratio_pro_pct)          || null) : null;

// ── Confiance ────────────────────────────────────────
let confiance = (parsed.confiance || 'BASSE').toUpperCase();
if (!['HAUTE','MOYENNE','BASSE'].includes(confiance)) confiance = 'BASSE';
if (flagMixte && montantProEstime === null) confiance = 'BASSE';

// ── Bénéficiaire ─────────────────────────────────────
const beneficiaireFinale = (parsed.beneficiaire && parsed.beneficiaire.trim() !== '')
  ? parsed.beneficiaire.toUpperCase()
  : 'ANONYME';

return [{
  json: {
    // Zone A
    date:                 dateFinale,
    emetteur:             parsed.emetteur     || 'INCONNU',
    type_document:        type,
    beneficiaire:         beneficiaireFinale,
    objet:                parsed.objet        || '',
    // Zone B
    categorie:            (parsed.categorie      || '').toUpperCase(),
    sous_categorie:       (parsed.sous_categorie || '').toUpperCase(),
    confiance:            confiance,
    raison_doute:         raison_doute,
    mention_manuscrite:   parsed.mention_manuscrite || null,
    // Zone C
    montant_ttc:          ttc,
    est_financier:        parsed.est_financier !== false,
    flag_mixte:           flagMixte,
    montant_pro_estime:   montantProEstime,
    montant_perso_estime: montantPersoEstime,
    ratio_pro_pct:        ratioProPct,
    // Zone E
    _source:      sourceItem.source    || 'INCONNUE',
    _fileName:    sourceItem.fileName  || 'INCONNU',
    _originalUrl: sourceItem.fileUrl   || '',
    _empreinte:   sourceItem.empreinte || '',
    _hash:        sourceItem.hash      || '',
    _gmailId:     sourceItem.gmailId   || '',
    _fileId:      sourceItem.fileId    || 'INCONNU',
    _parseError:  false
  }
}];

// ══════════════════════════════════════════════════════════════
// NORMALISATION FISCALE + NOMENCLATURE DIFFÉRENCIÉE
// ══════════════════════════════════════════════════════════════
const items = $input.all();

return items.map(item => {
  const data = item.json;
  const type = (data.type_document || 'ADMIN').toUpperCase();

  // ── Calculs taxes ──────────────────────────────────────────
  const ttc = parseFloat(data.montant_ttc) || 0;

  // ── Helpers ────────────────────────────────────────────────
  function san(str, maxLen = 30) {
    if (!str && str !== 0) return 'INCONNU';
    return String(str).toUpperCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[^A-Z0-9]/g, '_')
      .replace(/_{2,}/g, '_')
      .replace(/^_+|_+$/g, '')
      .substring(0, maxLen);
  }

  const date    = data.date || new Date().toISOString().split('T')[0];
  const emet    = san(data.emetteur, 25);
  const objet   = san(data.objet || data.sous_categorie, 25);
  const benef   = san(data.beneficiaire, 20);
  const montant = String(Math.round(ttc * 100) / 100).replace('.', '-');

  // ── Nomenclature selon type_document ──────────────────────
  let cleanName = data.clean_filename || '';

  // Reconstruire proprement selon le type (en cas de clean_filename absent ou mal formé)
  const FINANCIAL = ['FACTURE', 'RECU'];
  const isFinancial = FINANCIAL.includes(type) || data.est_financier === true;

  if (!cleanName || cleanName === 'DOCUMENT') {
    const cat = san(data.categorie, 20);
    const hasBenef = benef && benef !== 'ANONYME' && benef !== 'INCONNU';

    if (isFinancial) {
      // DATE-CAT-EMETTEUR-OBJET[-BENEF]-MONTANT.pdf
      const parts = [date, cat, emet, objet];
      if (hasBenef) parts.push(benef);
      parts.push(montant);
      cleanName = parts.join('-') + '.pdf';

    } else if (type === 'CONTRAT') {
      cleanName = `CONTRAT-${emet}-${objet}-${date}.pdf`;

    } else if (type === 'COURRIER') {
      cleanName = `COURRIER-${emet}-${objet}-${date}.pdf`;

    } else if (type === 'RELEVE') {
      // Période = objet (ex: MARS_2026) ou date
      cleanName = `RELEVE-${emet}-${objet}-${date}.pdf`;

    } else if (type === 'IDENTITE' || type === 'IMMIGRATION') {
      const parts = ['IDENTITE', emet, objet];
      if (hasBenef) parts.push(benef);
      parts.push(date);
      cleanName = parts.join('-') + '.pdf';

    } else if (type === 'MEDICAL') {
      const parts = ['MEDICAL', emet, objet];
      if (hasBenef) parts.push(benef);
      parts.push(date);
      cleanName = parts.join('-') + '.pdf';

    } else {
      // ADMIN générique
      cleanName = `ADMIN-${emet}-${objet}-${date}.pdf`;
    }
  }

  // Nettoyage final du nom généré (ou fourni par Gemini)
  cleanName = cleanName
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9._-]/g, '_')
    .replace(/_{2,}/g, '_')
    .replace(/^_+|_+$/g, '')
    .toUpperCase()
    .substring(0, 120);

  return {
    json: {
      ...data,
      type_document:  type,
      est_financier:  isFinancial,
      clean_filename: cleanName,
      beneficiaire:   benef,
      montant_ttc: Math.round(ttc * 100) / 100,
      date_journal:   date,
      _isFiscal:      ['PRO','AUTONOME','MAISON_BUREAU','PRIV_SANTE','PRIV_AUTO','MIXTE'].includes(
                        (data.categorie||'').toUpperCase()
                      )
    }
  };
});

/**
 * ROUTEUR FISCAL V8 - GED SENTINELLE
 * Fix: déaccentation emetteur + beneficiaire (apostrophes, tirets)
 */

const input = $input.first().json;

// ── Helper déaccentation ─────────────────────────────
function deaccent(str) {
  return (str || '')
    .toUpperCase()
    .replace(/[''`']/g, '')
    .replace(/[-–—]/g, '_')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Z0-9]/g, '_')
    .replace(/_{2,}/g, '_')
    .replace(/^_+|_+$/g, '');
}

let emetteur     = deaccent(input.emetteur     || 'INCONNU');
let beneficiaire = deaccent(input.beneficiaire || 'ANONYME');
let categorie    = (input.categorie || 'PRIV_VIE').toUpperCase();
let montant_ttc  = parseFloat(input.montant_ttc) || 0;

// ── CALCUL TAXES ─────────────────────────────────────
let note_fiscale = '';

if (categorie === 'AUTONOME') {
  note_fiscale = 'DÉDUCTIBLE 100% (CTI/RTI)';
}
else if (categorie === 'PRO')           note_fiscale = 'REMBOURSABLE EMPLOYEUR';
else if (categorie === 'MAISON_BUREAU') note_fiscale = 'PRORATA BUREAU DOMICILE (ligne 9270)';
else if (categorie === 'PRIV_SANTE')   note_fiscale = 'CRÉDIT FRAIS MÉDICAUX (ligne 381)';
else if (categorie === 'PRIV_AUTO')    note_fiscale = 'FRAIS VÉHICULE — vérifier usage mixte';
else if (input.flag_mixte)             note_fiscale = '⚠️ À VENTILER (MARCHAND GÉNÉRALISTE)';

// ── CATÉGORIES FISCALES ───────────────────────────────
const FISCAL_CATEGORIES = [
  'PRO', 'AUTONOME', 'MAISON_BUREAU',
  'PRIV_SANTE', 'PRIV_AUTO', 'MIXTE'
];

const isFiscal = FISCAL_CATEGORIES.includes(categorie);

// ── NOM DE FICHIER ────────────────────────────────────
let cleanName = (input.clean_filename || 'DOCUMENT').toString();
cleanName = cleanName
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-zA-Z0-9._-]/g, '_')
  .replace(/_{2,}/g, '_')
  .replace(/^_+|_+$/g, '')
  .toUpperCase();

// ── DOSSIER CIBLE ─────────────────────────────────────
const ID_PARENT_IMPOTS  = $env.GED_IMPOTS_PARENT_ID;
const ID_PARENT_ARCHIVE = $env.GED_ARCHIVE_FOLDER_ID;

let fiscalYear = new Date().getFullYear();
try { if (input.date) fiscalYear = new Date(input.date).getFullYear(); } catch(e) {}

const targetFolderName = isFiscal ? `Impôts ${fiscalYear}` : '_GED_ARCHIVE';

// ── VALIDATION REQUISE ? ──────────────────────────────
const _needsValidation = input.flag_mixte === true
  || (input.confiance || '').toUpperCase() === 'BASSE';

return [{
  json: {
    ...input,
    date:                input.date || new Date().toISOString().split('T')[0],
    emetteur:            emetteur,
    categorie:           categorie,
    sous_categorie:      (input.sous_categorie || 'DIVERS').toUpperCase(),
    beneficiaire:        beneficiaire,
    montant_ttc:         Number(montant_ttc.toFixed(2)),
    note_fiscale:        note_fiscale,
    clean_filename:      cleanName,
    _isFiscal:           isFiscal,
    _targetFolderName:   targetFolderName,
    _impotsParentId:     ID_PARENT_IMPOTS,
    _archiveFolderId:    ID_PARENT_ARCHIVE,
    _needsValidation:    _needsValidation,
    _fiscalYear:         fiscalYear,
    dossier_destination: isFiscal ? 'FISCAL' : 'ARCHIVE'
  }
}];

// ══════════════════════════════════════════════════
// PRÉPARER STAGING — Nomenclature Zone A→E unifiée (v2)
// ══════════════════════════════════════════════════
const d = $input.first().json;

return [{
  json: {
    // Zone A
    Date:                 d.date           || '',
    Emetteur:             d.emetteur       || 'INCONNU',
    Type_Document:        d.type_document  || 'ADMIN',
    Beneficiaire:         d.beneficiaire   || 'ANONYME',
    Objet:                d.objet || d.sous_categorie || '',
    // Zone B
    Categorie:            d.categorie      || '',
    Sous_Categorie:       d.sous_categorie || '',
    Confiance:            d.confiance      || 'BASSE',
    Raison_Doute:         d.raison_doute   || '',
    Mention_Manuscrite:   d.mention_manuscrite || '',
    // Zone C
    Montant_TTC:          d.montant_ttc    || 0,
    Est_Financier:        d.est_financier !== false,
    Flag_Mixte:           d.flag_mixte     || false,
    Montant_Pro_Estime:   d.montant_pro_estime   ?? '',
    Montant_Perso_Estime: d.montant_perso_estime ?? '',
    Ratio_Pro_Pct:        d.ratio_pro_pct         ?? '',
    // Zone D — vide intentionnellement (saisie manuelle)
    Est_Valide_Mixte:     '',
    Montant_Pro_Valide:   '',
    // Zone E
    Source:               d._source       || '',
    File_Name:            d._fileName     || '',
    Lien_Drive:           d._originalUrl  || '',
    Empreinte:            d._empreinte    || '',
    Hash:                 d._hash         || '',
    Gmail_Id:             d._gmailId      || '',
    File_Id:              d._fileId       || '',
    // Colonnes machine étendues (_STAGING uniquement)
    _isFiscal:            d._isFiscal     || false,
    _fiscalYear:          d._fiscalYear   || new Date().getFullYear(),
    _targetFolderName:    d._targetFolderName || '',
    _impotsParentId:      d._impotsParentId  || '',
    _archiveFolderId:     d._archiveFolderId || '',
    processedAt:          new Date().toISOString(),
    statut:               'EN_ATTENTE'
  }
}];

const d = $input.first().json;
const source = d._source
  || $('⚙️ Normaliser Source').first().json.source
  || 'INCONNUE';

let empreinte = '';
try { empreinte = $('🧬 WD — Calculer Empreinte').first().json._empreinte || ''; } catch(e) {}

let hash = '';
try { hash = $('🔐 WD L0 — Calculer Hash').first().json._hash || ''; } catch(e) {}

return [{
  json: {
    ...d,
    _source:           source,
    _empreinte:        empreinte,
    _hash:             hash,
    _validationMethod: 'AUTO_IA',
    _finalFileName:    d.clean_filename || 'DOCUMENT_SANS_NOM.pdf',
    _sheetRow: {
      // Zone A
      Date:                 d.date           || '',
      Emetteur:             d.emetteur       || 'INCONNU',
      Type_Document:        d.type_document  || 'ADMIN',
      Beneficiaire:         d.beneficiaire   || 'ANONYME',
      Objet:                (d.objet && d.objet !== '') ? d.objet.toUpperCase() : (d.sous_categorie || 'DIVERS'),
      // Zone B
      Categorie:            d.categorie      || 'INCONNUE',
      Sous_Categorie:       d.sous_categorie || '',
      Confiance:            d.confiance      || 'BASSE',
      Raison_Doute:         d.raison_doute   || '',
      Mention_Manuscrite:   d.mention_manuscrite || '',
      // Zone C
      Montant_TTC:          d.montant_ttc    || 0,
      Est_Financier:        d.est_financier !== false,
      Flag_Mixte:           d.flag_mixte     || false,
      Montant_Pro_Estime:   d.montant_pro_estime   ?? '',
      Montant_Perso_Estime: d.montant_perso_estime ?? '',
      Ratio_Pro_Pct:        d.ratio_pro_pct         ?? '',
      // Zone D — vide intentionnellement
      Est_Valide_Mixte:     '',
      Montant_Pro_Valide:   '',
      // Zone E
      Source:               source,
      File_Name:            d._fileName  || '',
      Lien_Drive:           '',
      Empreinte:            empreinte,
      Hash:                 hash,
      Gmail_Id:             d._gmailId   || '',
      File_Id:              d._fileId    || ''
    }
  }
}];

// ══════════════════════════════════════════════════
// RÉSOUDRE DOSSIER CIBLE
// Fiscal   → chercher/créer "Impôts YYYY" sous parent Impôts
// Archive  → utiliser GED_ARCHIVE_FOLDER_ID directement
// ══════════════════════════════════════════════════
const d = $input.first().json;

if (!d._isFiscal) {
  // Pas de recherche — l'ID archive EST le dossier cible
  return [{ json: {
    ...d,
    _resolveFolder:   false,
    _resolvedFolderId: $env.GED_ARCHIVE_FOLDER_ID
  }}];
}

// Fiscal → déclencher la recherche du dossier Impôts YYYY
return [{ json: {
  ...d,
  _resolveFolder: true,
  _resolvedFolderId: null
}}];

// ══════════════════════════════════════════════════
// RÉSOUDRE ID FINAL
// Cas 1: non-fiscal → _resolvedFolderId déjà injecté
// Cas 2: dossier trouvé via Search → files[0].id
// Cas 3: dossier créé → id direct
// ══════════════════════════════════════════════════
