// ══════════════════════════════════════════════════
// WATCHDOG EMPREINTE — Après analyse Gemini
// Empreinte: DATE_EMETTEUR_OBJET_BENEFICIAIRE_MONTANT
//
// Discriminants:
//   DATE       → évite les confusions inter-périodes
//   EMETTEUR   → identifie le prestataire
//   OBJET      → distingue 2 prestations différentes
//              → même jour, même prestataire, même montant
//   BENEFICIAIRE → distingue 2 bénéficiaires différents
//              → même jour, même prestataire, même objet
//   MONTANT    → inclus seulement si doc financier
//              → exclu si 0 (doc non-financier) car trop générique
// ══════════════════════════════════════════════════
const d = $input.first().json;

const date      = (d.date || d.date_journal || '').substring(0, 10);
const emetteur  = (d.emetteur || '').toUpperCase()
                    .replace(/[^A-Z0-9]/g,'_')
                    .replace(/_{2,}/g,'_')
                    .substring(0, 20);
const objet     = (d.objet || d.sous_categorie || 'DIVERS').toUpperCase()
                    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
                    .replace(/[^A-Z0-9]/g,'_')
                    .replace(/_{2,}/g,'_')
                    .substring(0, 20);
const benef     = (d.beneficiaire || 'ANONYME').toUpperCase()
                    .replace(/[^A-Z0-9]/g,'_')
                    .replace(/_{2,}/g,'_')
                    .substring(0, 15);
const ttc       = parseFloat(d.montant_ttc) || 0;
const montant   = String(Math.round(ttc * 100));

// Empreinte complète — montant inclus seulement si doc financier
const isFinancial = ['FACTURE','RECU'].includes((d.type_document||'').toUpperCase())
                    || d.est_financier === true;

const parts = [date, emetteur, objet, benef];
if (isFinancial && ttc > 0) parts.push(montant);

const empreinte = parts.join('_');

return [{
  json: {
    ...d,
    _empreinte:    empreinte,
    _empParts: { date, emetteur, objet, benef, montant: isFinancial ? montant : 'N/A' }
  }
}];

// ══════════════════════════════════════════════════
// WATCHDOG — Interpréter résultat recherche empreinte
// Reçoit réponse HTTP API Sheets colonne K
// ══════════════════════════════════════════════════
const empreinteRecherchee = $('🧬 WD — Calculer Empreinte').first().json._empreinte || '';
const resp = $input.first().json;
const col = (resp.values || [])[0] || [];

const found = col.some((v, i) => i > 0 && v === empreinteRecherchee);

return [{
  json: {
    ...$('🧬 WD — Calculer Empreinte').first().json,
    _empreinteConnue: found,
    _length: found ? 1 : 0
  }
}];

// ══════════════════════════════════════════════════
// DOWNLOAD FILE — Route selon source (v2)
// Robuste : fallback si binaire absent
// ══════════════════════════════════════════════════
const sourceNode = $('⚙️ Normaliser Source').first().json;
const source = sourceNode.source || 'DRIVE';

if (source === 'GMAIL') {
  const pj = $('📎 Décoder PJ Base64').first();

  // Cas email sans PJ ou decode échoué
  if (pj.json._noAttachment || pj.json._decodeError || !pj.binary?.data) {
    console.warn('DOWNLOAD: Binaire Gmail absent — fallback vide');
    return [{
      json: {
        ...$input.first().json,
        _downloadError:   true,
        _downloadWarning: 'Binaire Gmail absent — document non traitable'
      },
      binary: {}
    }];
  }

  return [{
    json:   $input.first().json,
    binary: { data: pj.binary.data }
  }];
}

// DRIVE ou BATCH
const driveItem = $('⬇️ Download Drive').first();
if (!driveItem.binary?.data) {
  console.warn('DOWNLOAD: Binaire Drive absent — source:', source);
  return [{
    json: {
      ...$input.first().json,
      _downloadError:   true,
      _downloadWarning: `Binaire Drive absent (source: ${source}) — document non traitable`
    },
    binary: {}
  }];
}

return [{
  json:   $input.first().json,
  binary: { data: driveItem.binary.data }
}];

// ══════════════════════════════════════════════════
// WD L0 — Calculer Hash (FNV-1a multi-seed)
// 4 passes avec seeds différents → 32 chars hex
// ══════════════════════════════════════════════════
const item = $input.first();
const meta = $('⚙️ Normaliser Source').first().json;

function fnv1a32(bytes, offsetBasis) {
  let h = offsetBasis >>> 0;
  for (let i = 0; i < bytes.length; i++) {
    h ^= bytes[i];
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h;
}

function multiHash(bytes) {
  const len = bytes.length;
  const q   = Math.floor(len / 4);
  const s1 = bytes.slice(0,     Math.min(q, 8192));
  const s2 = bytes.slice(q,     Math.min(q * 2, q + 8192));
  const s3 = bytes.slice(q * 2, Math.min(q * 3, q * 2 + 8192));
  const s4 = bytes.slice(len - Math.min(q, 8192));
  const h1 = fnv1a32(s1, 0x811c9dc5);
  const h2 = fnv1a32(s2, 0x84222325);
  const h3 = fnv1a32(s3, 0xc9fb3f18);
  const h4 = fnv1a32(s4, 0x6b43a9b5);
  const ha = ((h1 ^ h3)           >>> 0).toString(16).padStart(8,'0');
  const hb = ((h2 ^ h4)           >>> 0).toString(16).padStart(8,'0');
  const hc = ((h1 ^ h2 ^ h3 ^ h4) >>> 0).toString(16).padStart(8,'0');
  const hs = (len                  >>> 0).toString(16).padStart(8,'0');
  return ha + hb + hc + hs;
}

let hash;
let hashSource = 'FALLBACK';

try {
  const raw = item.json?.data;
  if (raw && typeof raw === 'string' && raw.length > 10) {
    const bytes = Buffer.from(raw, 'base64');
    if (bytes.length > 0) {
      hash = multiHash(bytes);
      hashSource = 'BINARY_FNV1A_MULTI';
    }
  }
} catch(e) {}

if (!hash) {
  const fb = Buffer.from(
    (meta.fileId || '') + (meta.fileName || '') + (meta.fileUrl || ''),
    'utf8'
  );
  hash = multiHash(fb);
  hashSource = 'FALLBACK_FILEID';
}

return [{
  json: { ...item.json, _hash: hash, _hashSource: hashSource },
  binary: item.binary
}];

// ══════════════════════════════════════════════════
// WD L0 — Chercher Hash dans 3 sources (tout-en-un)
// Remplace Merge + 3 HTTP + Analyser Hash
// Appels séquentiels → pas d'accumulation de contexte
// ══════════════════════════════════════════════════
const hashItem = $('🔐 WD L0 — Calculer Hash').first();
const hash     = hashItem.json._hash || '';
const meta     = hashItem.json;
const sheetId  = $env.GED_SHEET_ID;

if (!hash) {
  return [{ json: { ...meta, _hashDoublon: false, _hashDoublonSource: null, _hash: hash }, binary: hashItem.binary }];
}

async function searchHash(range) {
  try {
    const url = `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/${encodeURIComponent(range)}?majorDimension=COLUMNS`;
    const resp = await $helpers.httpRequest({
      method: 'GET',
      url,
      authentication: 'predefinedCredentialType',
      nodeCredentialType: 'googleSheetsOAuth2Api',
    });
    const col = (resp.values || [])[0] || [];
    return col.some((v, i) => i > 0 && String(v).trim() === String(hash).trim());
  } catch(e) {
    return false;
  }
}

// Recherches séquentielles — pas de parallélisme → pas d'accumulation
const inFiscal  = await searchHash('Journal_Fiscal!W:W');
const inGED     = await searchHash('Journal_GED!W:W');
const inStaging = await searchHash('_STAGING!W:W');

const isDoublon = inFiscal || inGED || inStaging;
const source    = inFiscal  ? 'JOURNAL_FISCAL'
                : inGED     ? 'JOURNAL_GED'
                : inStaging ? 'STAGING'
                : null;

return [{
  json: {
    ...meta,
    _hashDoublon:       isDoublon,
    _hashDoublonSource: source,
    _hash:              hash
  },
  binary: hashItem.binary
}];

// Liste des catégories
const categories = [
  "AUTONOME", "PRO", "MAISON_BUREAU", "PRIV_SANTE",
  "PRIV_AUTO", "PRIV_VIE", "MIXTE", "IGNORER"
];

// Créer les boutons
const buttons = categories.map(cat => ({
  text: cat,
  callback_data: cat
}));

// Grouper les boutons par 2
const keyboard = [];
for (let i = 0; i < buttons.length; i += 2) {
  keyboard.push(buttons.slice(i, i + 2));
}

// Préparer la structure pour Telegram
const reply_markup = { inline_keyboard: keyboard };

// Ajouter la structure à l'item
return [{
  json: {
    ...$input.first().json,
    reply_markup: reply_markup
  }
}];

// ══════════════════════════════════════════════════
// RETOUR BATCH — Expose les données pour Collecter Résultats
// Exécuté uniquement en mode BATCH (Mode Silencieux ?4 FALSE)
// ══════════════════════════════════════════════════
const d = $('🔗 Injecter Lien Drive').first().json;
return [{ json: {
  date:           d.date           || '',
  emetteur:       d.emetteur       || '',
  objet:          d.objet          || '',
  beneficiaire:   d.beneficiaire   || '',
  montant_ttc:    d.montant_ttc    || 0,
  categorie:      d.categorie      || '',
  sous_categorie: d.sous_categorie || '',
  confiance:      d.confiance      || '',
  raison_doute:   d.raison_doute   || d.note_fiscale || '',
  clean_filename: d.clean_filename || d._finalFileName || '',
  _driveLink:     d._driveLink     || '',
  _hash:          d._hash          || '',
  _empreinte:     d._empreinte     || '',
  _isFiscal:      d._isFiscal      || false,
  _hashDoublon:   d._hashDoublon   || false,
  _isDoublon:     d._isDoublon     || false,
  _fileId:        d._fileId        || d.fileId   || '',
  _fileName:      d._fileName      || d.fileName || '',
  _source:        'BATCH'
}}];

// Retour minimal pour BATCH en cas de doublon détecté
const meta = $('⚙️ Normaliser Source').first().json;
return [{ json: {
  _fileId:      meta.fileId   || '',
  _fileName:    meta.fileName || '',
  _source:      'BATCH',
  _isDoublon:   true,
  _isFiscal:    false,
  _hashDoublon: false,
  date: '', emetteur: '', objet: '', beneficiaire: '',
  montant_ttc: 0, categorie: '', sous_categorie: '',
  confiance: '', raison_doute: 'DOUBLON', clean_filename: '',
  _driveLink: '', _hash: '', _empreinte: ''
}}];

// ══════════════════════════════════════════════════
// COMPTER & LISTER PJ — Pré-processing Gmail multi-PJ (v1)
// Retourne 1 item par PJ éligible
// Chaque item porte _attachId, _attachIndex, _attachTotal
// Si 0 PJ → 1 item placeholder _noAttachment
// ══════════════════════════════════════════════════
const msg = $input.first().json;

// ── Helper: extraire email brut ──
function extractEmail(raw) {
  if (!raw) return '';
  const angle = raw.match(/<([^>]+)>/);
  if (angle) return angle[1].trim().toLowerCase();
  const plain = raw.match(/([^\s<>"',;]+@[^\s<>"',;]+)/);
  return plain ? plain[1].trim().toLowerCase() : raw.trim().toLowerCase();
}

// ── Validation alias +scan (double-check ici aussi) ──
const headers  = msg.payload?.headers || [];
const ALIAS    = ($env.GED_GMAIL_ALIAS || 'debourouba+scan@gmail.com').toLowerCase();
const toRaw    = headers.find(h => h.name?.toLowerCase() === 'to')?.value || '';
const delRaw   = headers.find(h => h.name?.toLowerCase() === 'delivered-to')?.value || '';
const toEmail  = extractEmail(toRaw);
const delEmail = extractEmail(delRaw);

const isTargeted = toEmail.includes(ALIAS) || delEmail.includes(ALIAS);
if (!isTargeted) {
  console.warn(`Compter PJ: email ignoré — alias non détecté. To="${toRaw}" Del="${delRaw}"`);
  return []; // stoppe le flux pour cet email
}

// ── MIME types acceptés ──
const ELIGIBLE = ['application/pdf','image/jpeg','image/jpg',
                  'image/png','image/heic','image/webp','image/tiff'];

// ── Traversée récursive des parts ──
function findAttachments(parts, results = []) {
  if (!Array.isArray(parts)) return results;
  for (const part of parts) {
    const hasAttachId = !!part.body?.attachmentId;
    const hasFilename = !!(part.filename && part.filename.trim().length > 0);
    const isEligible  = ELIGIBLE.some(m => (part.mimeType || '').toLowerCase().includes(
                          m.split('/')[1]
                        ));
    if (hasAttachId && hasFilename && isEligible) {
      results.push({
        attachmentId: part.body.attachmentId,
        filename:     part.filename.trim(),
        mimeType:     part.mimeType,
        size:         part.body.size || 0,
        partId:       part.partId || ''
      });
    }
    if (Array.isArray(part.parts)) findAttachments(part.parts, results);
  }
  return results;
}

const attachments = findAttachments(msg.payload?.parts || []);
const total       = attachments.length;

// Extraire sujet et expéditeur pour enrichissement
const hFrom    = headers.find(h => h.name?.toLowerCase() === 'from');
const hSubject = headers.find(h => h.name?.toLowerCase() === 'subject');
const fromAddr = hFrom?.value    || '';
const subject  = hSubject?.value || '';

console.log(`📎 Gmail ${msg.id} — PJ détectées: ${total} | Alias OK: ${isTargeted}`);

// ── Cas 0 PJ éligible ─────────────────────────────
if (total === 0) {
  return [{
    json: {
      // Champs isGmail detection pour Normaliser Source
      threadId:     msg.threadId,
      historyId:    msg.historyId,
      id:           msg.id,
      labels:       msg.labelIds || [],
      from:         fromAddr,
      subject:      subject,
      payload:      msg.payload, // garder pour isValidScanTarget dans Normaliser Source
      // Métadonnées PJ
      _attachId:    null,
      _attachIndex: 1,
      _attachTotal: 0,
      _noAttachment: true,
      fileName:     `email_${msg.id}.pdf`,
      mimeType:     'application/pdf'
    }
  }];
}

// ── Cas N PJ → N items ────────────────────────────
return attachments.map((att, i) => ({
  json: {
    // Champs isGmail detection
    threadId:  msg.threadId,
    historyId: msg.historyId,
    id:        msg.id,
    labels:    msg.labelIds || [],
    from:      fromAddr,
    subject:   subject,
    payload:   msg.payload,
    // Métadonnées PJ spécifiques
    _attachId:    att.attachmentId,
    _attachIndex: i + 1,
    _attachTotal: total,
    fileName:     att.filename,
    mimeType:     att.mimeType,
    _attachSize:  att.size,
    _partId:      att.partId
  }
}));
